export type Action = 'Resumen'|'Inventario'|'Solicitudes'|'Donantes'|'Registrar unidad'|'Ver inventario'|'Ver todas';
export function routeFor(action:Action):string { const routes:Record<Action,string>={Resumen:'/',Inventario:'/inventario',Solicitudes:'/solicitudes',Donantes:'/donantes','Registrar unidad':'/inventario/nueva','Ver inventario':'/inventario','Ver todas':'/solicitudes'}; return routes[action]; }
